head.script:


scwin.getType = function ( info ) {

	var rowIndex = info.rowIndex;
	var colIndex = info.colIndex;
	var returnInfo;

	if (dataList1.getCellData(rowIndex, "col2") == 1 | dataList1.getCellData(rowIndex, "col2") == 2 || dataList1.getCellData(rowIndex, "col2") == 3) {
		returnInfo = {
			id : "dynamic_trigger_" + rowIndex + "_" + colIndex,
			inputType : "button",
			options : {
				viewType: "icon", 
				chooseOption:"true"
			}
		};

	} else {
		returnInfo = {
               id : "dynamic_text_" + rowIndex + "_" + colIndex,
			inputType : "text",
			options : {
			}
		};
	}

	if(returnInfo) {
		//console.log( "[typeGetter] (" + rowIndex + ", " + colIndex + ") : " +returnInfo.inputType);
	}

	return returnInfo;
};


scwin.grd_onviewchange = function(info) {
	console.log("---> onviewchange");
	grd.refreshRow(info.rowIndex);
};

scwin.onpageload = function() {
	var jsonData = [
		{
			"col1": "value1",
			"col2": "1"
		},{
			"col1": "value2",
			"col2": "2"
		},{
			"col1": "value3",
			"col2": "3"
		},{
			"col1": "value4",
			"col2": "4"
		}
	];
    dataList1.setJSON( jsonData );
};

scwin.onpageunload = function() {

};

scwin.trigger01_onclick = function (e) {
	var options = {
		inputType : "button"
	}
	dataList1.insertRow(0, options);
};

scwin.trigger02_onclick = function (e) {
	dataList1.removeRow(0);
};

scwin.trigger03_onclick = function (e) {
	var a = grd.getCellInfo(0,0)
	console.log( a.cellManagerHashByID );
};

	scwin.checkVal = function() {
		for (var key in grd.getCellInfo(0,0).cellManagerHashByID) {
		  if (grd.getCellInfo(0,0).cellManagerHashByID.hasOwnProperty(key)) {
			console.log(key + ': ' + grd.getCellInfo(0,0).cellManagerHashByID[key]);
				if(grd.getCellInfo(0,0).cellManagerHashByID[key] === null)
					return false;
		  }
		}
		return true;
	}

	scwin.checkVal2 = function() {
		for (var key in grd.getCellInfo(0,0).cellManagerHashByID) {
		  if (grd.getCellInfo(0,0).cellManagerHashByID.hasOwnProperty(key)) {
			console.log(key + ': ' + grd.getCellInfo(0,0).cellManagerHashByID[key]);
				if(grd.getCellInfo(0,0).cellManagerHashByID[key] === null)
					return false;
		  }
		}
		return true;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger01').click()");
		WebSquare.wUnit.addCommand("pause", "500");						
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger03').click()");
		WebSquare.wUnit.addCommand("pause", "500");						
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger02').click()");
		WebSquare.wUnit.addCommand("pause", "500");						
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger03').click()");
		WebSquare.wUnit.addCommand("pause", "500");						
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
